-- Shared plain-table contracts. No game calls or imported execution.
local K={schema=1}
function K.finite(x) return type(x)=='number' and x==x and math.abs(x)<1e12 end
function K.context(c)
    if type(c)~='table' then return false end
    for _,k in ipairs({'accountId','universeId','epoch'}) do if not K.finite(c[k]) or c[k]<0 then return false end end
    for _,k in ipairs({'jobId','roundId','stageId','mode'}) do if type(c[k])~='string' or #c[k]<1 or #c[k]>200 then return false end end
    return true
end
function K.same(a,b,scope)
    if not K.context(a) or not K.context(b) then return false end
    for _,k in ipairs({'accountId','universeId','jobId','epoch'}) do if a[k]~=b[k] then return false end end
    if scope=='account' or scope=='static' then return true end
    return a.roundId==b.roundId and a.stageId==b.stageId and a.mode==b.mode
end
function K.cost(cost)
    if type(cost)~='table' then return false end
    local n=0
    for id,amount in pairs(cost) do
        n+=1
        if n>16 or type(id)~='string' or #id<1 or #id>100 or not K.finite(amount) or amount<0 then return false end
    end
    return true
end
function K.intent(x)
    return type(x)=='table' and type(x.id)=='string' and #x.id>0 and #x.id<=200
        and type(x.capabilityId)=='string' and type(x.kind)=='string' and K.context(x.context)
        and K.cost(x.cost) and K.finite(x.deadline) and type(x.expected)=='table'
end
function K.copy(t,depth)
    if type(t)~='table' then return t end
    depth=depth or 0;if depth>12 then return nil end
    local out={};local n=0
    for k,v in pairs(t) do
        n+=1;if n>2000 then break end
        if type(k)=='string' or type(k)=='number' then
            if type(v)=='table' then out[k]=K.copy(v,depth+1)
            elseif type(v)=='string' or type(v)=='boolean' or (K.finite(v)) then out[k]=v end
        end
    end
    return out
end
return K

end)()

__modules.evidence = (function()
-- Each instance owns its capability registry. Observed age is not server freshness.
return function(K)
    local E={capabilities={}}
    function E.register(c)
        assert(type(c)=='table' and type(c.id)=='string' and type(c.requiredFields)=='table','Invalid capability')
        E.capabilities[c.id]=K.copy(c)
    end
    function E.inspect(id,view,now)
        local cap=E.capabilities[id]
        local function no(reason) return {ready=false,reason=reason,evidence=cap} end
        if not cap or cap.status=='missing' then return no('Capability unavailable: '..tostring(id)) end
        if type(view)~='table' or not K.context(view.context) or not K.finite(now) then return no('Lifecycle identity unavailable') end
        for _,key in ipairs(cap.requiredFields) do
            local ev=type(view.evidence)=='table' and view.evidence[key]
            if view[key]==nil or type(ev)~='table' or ev.complete~=true then return no('Incomplete '..key) end
            if ev.schema~=cap.schema then return no('Unsupported '..key..' schema') end
            if not K.same(ev.context,view.context,ev.scope) then return no('Changed '..key..' context') end
            if type(ev.source)~='string' or ev.source=='' then return no('Missing '..key..' source') end
            if ev.scope~='static' then
                local maxAge=ev.scope=='offer' and 2 or 5
                if not K.finite(ev.observedAt) or now<ev.observedAt or now-ev.observedAt>maxAge then return no('Stale '..key) end
            end
        end
        return {ready=true,reason='Observed; server freshness not established',evidence=cap}
    end
    function E.capture(view,limits)
        limits=limits or {};local maxBytes=math.clamp(tonumber(limits.bytes) or 65536,256,65536)
        local maxNodes=math.clamp(tonumber(limits.nodes) or 2000,10,2000)
        local bytes,nodes,truncated=0,0,false
        local function safe(v,depth)
            nodes+=1;if nodes>maxNodes or depth>10 then truncated=true;return nil end
            local typ=type(v)
            if typ=='string' then
                local s=v:sub(1,300);if bytes+#s+8>maxBytes then truncated=true;return nil end
                bytes+=#s+8;return s
            elseif typ=='number' and K.finite(v) then bytes+=24;return v
            elseif typ=='boolean' then bytes+=8;return v
            elseif typ=='table' then
                local out={};local count=0
                for key,value in pairs(v) do
                    count+=1;if count>400 or bytes+40>maxBytes then truncated=true;break end
                    local lower=type(key)=='string' and key:lower() or ''
                    local private=lower:find('uuid',1,true) or lower:find('token',1,true) or lower:find('webhook',1,true)
                        or lower:find('secret',1,true) or lower:find('password',1,true) or lower=='accountid' or lower=='userid' or lower=='jobid'
                    if not private and (type(key)=='number' or (type(key)=='string' and #key<=100)) then
                        bytes+=type(key)=='string' and #key+4 or 12
                        local valueCopy=safe(value,depth+1);if valueCopy~=nil then out[key]=valueCopy end
                    end
                end
                return out
            end
            return nil
        end
        local allowed={'now','context','evidence','roster','towers','battlefield','threats','flow','dungeon','account','goals'}
        local out={}
        for _,key in ipairs(allowed) do if type(view)=='table' and view[key]~=nil then out[key]=safe(view[key],0) end end
        out.bytes=math.min(bytes,maxBytes);out.truncated=truncated;out.schema=K.schema
        return out
    end
    return E
end

end)()

__modules.budget = (function()
-- Durable reservation ledger. It never sends gameplay requests.
return function(K,io,identity,clock)
    local B={state={schema=1,identity=K.copy(identity),caps={},spent={},reservations={},closed={}}}
    local function persist(nextState,allowVolatile)
        -- Free round actions never rewrite the account ledger. Their same-job
        -- uncertainty fence is retained by the native transport, not disk IO.
        if allowVolatile then B.state=nextState;B.volatile=true;return true end
        local ok,result=false,false
        if type(io.write)=='function' then ok,result=pcall(io.write,K.copy(nextState)) end
        if not ok or result~=true then
            if allowVolatile then B.state=nextState;B.volatile=true;return true end
            return false,'Budget checkpoint write/read failed'
        end
        B.state=nextState;return true
    end
    local function sameIdentity(a,b) return type(a)=='table' and type(b)=='table' and a.accountId==b.accountId and a.universeId==b.universeId end
    function B.review(policy,view)
        if type(policy)~='table' or not K.cost(policy.caps) or type(policy.allowedOps)~='table'
            or type(policy.id)~='string' or not K.finite(policy.expires) or policy.expires<=clock()
            or policy.expires>clock()+7200 or not K.context(view.context) or not sameIdentity(identity,view.context) then return nil end
        return {id=policy.id,caps=K.copy(policy.caps),allowedOps=K.copy(policy.allowedOps),expires=policy.expires,
            identity=K.copy(identity),context=K.copy(view.context),reviewedAt=clock()}
    end
    function B.grant(preview,ack)
        if B.frozen or (type(io.canPay)=='function' and io.canPay()~=true) then return nil,'Account storage unavailable or needs reconciliation' end
        if ack~=true or type(preview)~='table' or not sameIdentity(preview.identity,identity)
            or not K.finite(preview.reviewedAt) or clock()-preview.reviewedAt>30 or preview.expires<=clock() then return nil end
        for _,r in pairs(B.state.reservations) do if r.sent and next(r.cost)~=nil then return nil,'Outstanding debit unresolved' end end
        -- Reusing an ID retains all original debits and caps; START cannot reset it.
        if B.state.grant and B.state.grant.id==preview.id then return K.copy(B.state.grant) end
        local nextState={schema=1,identity=K.copy(identity),caps=K.copy(preview.caps),spent={},reservations={},closed={},grant=K.copy(preview)}
        if not persist(nextState) then return nil end
        return K.copy(B.state.grant)
    end
    function B.remaining(resource)
        local n=(B.state.caps[resource] or 0)-(B.state.spent[resource] or 0)
        for _,r in pairs(B.state.reservations) do n-=r.cost[resource] or 0 end
        return math.max(0,n)
    end
    function B.reserve(intent)
        if not K.intent(intent) or B.state.reservations[intent.id] or B.state.closed[intent.id] then return false,'Invalid/duplicate intent' end
        local paid=false;for _,n in pairs(intent.cost) do if n>0 then paid=true end end
        local grant=B.state.grant
        if paid then
            if not grant or intent.permissionId~=grant.id or grant.expires<=clock()
                or grant.allowedOps[intent.capabilityId]~=true or not sameIdentity(intent.context,identity) then return false,'Spending grant unavailable' end
            for _,r in pairs(B.state.reservations) do if r.sent and next(r.cost)~=nil then return false,'Outstanding account action' end end
            for id,n in pairs(intent.cost) do if n>B.remaining(id) or n<=0 or (B.state.caps[id] or 0)<=0 then return false,'Resource cap reached: '..id end end
        end
        local state=K.copy(B.state);state.reservations[intent.id]={cost=K.copy(intent.cost),context=K.copy(intent.context),sent=false}
        return persist(state,not paid)
    end
    function B.sent(id)
        if not B.state.reservations[id] then return false end
        local state=K.copy(B.state);state.reservations[id].sent=true
        return persist(state,next(state.reservations[id].cost)==nil)
    end
    function B.cancel(id)
        local r=B.state.reservations[id];if not r or r.sent then return false end
        local state=K.copy(B.state);state.reservations[id]=nil;return persist(state,next(r.cost)==nil)
    end
    function B.settle(receipt)
        local r=type(receipt)=='table' and B.state.reservations[receipt.intentId]
        if not r or not r.sent then return false end
        if receipt.status~='confirmed' or receipt.proof~=true or not K.cost(receipt.debits or {}) then return false end
        for id,n in pairs(r.cost) do if (receipt.debits or {})[id]~=n then return false end end
        for id,n in pairs(receipt.debits or {}) do if r.cost[id]~=n then return false end end
        local state=K.copy(B.state)
        for id,n in pairs(r.cost) do state.spent[id]=(state.spent[id] or 0)+n end
        state.reservations[receipt.intentId]=nil;state.closed[receipt.intentId]=true
        local count=0;for _ in pairs(state.closed) do count+=1 end
        if count>2000 then return false,'Ledger full; review a new budget' end
        return persist(state,next(r.cost)==nil)
    end
    function B.checkpoint() return K.copy(B.state) end
    function B.invalidateRound(context)
        local state=K.copy(B.state)
        for id,r in pairs(state.reservations) do
            if next(r.cost)==nil and not K.same(r.context,context) then state.reservations[id]=nil end
        end
        return persist(state,true)
    end
    function B.restore(data,currentIdentity)
        if type(data)~='table' or data.schema~=1 or not sameIdentity(data.identity,identity)
            or not sameIdentity(identity,currentIdentity) or not K.cost(data.caps) or not K.cost(data.spent)
            or type(data.reservations)~='table' or type(data.closed)~='table' then return false end
        local count=0
        for id,r in pairs(data.reservations) do
            count+=1
            if count>32 or type(id)~='string' or type(r)~='table' or not K.cost(r.cost) or not K.context(r.context) or type(r.sent)~='boolean' then return false end
        end
        B.state=K.copy(data);return true
    end
    return B
end

end)()

__modules.actions = (function()
-- One writer for domain intents. Transport success alone never confirms an action.
return function(K,evidence,budget,io)
    local A={current=nil,halted=false,reason=''}
    local function decision(kind,reason,intent) return {kind=kind,reason=reason,intent=intent} end
    function A.submit(intent,view,run)
        if A.current then return decision('wait','Action awaits exact feedback') end
        if A.halted then return decision('stop',A.reason) end
        if not K.intent(intent) or not K.same(intent.context,view.context) or not K.finite(view.now) or view.now>=intent.deadline then
            return decision('stop','Invalid, expired or changed-context intent')
        end
        local observed=evidence.inspect(intent.capabilityId,view,view.now)
        if not observed.ready then return decision('stop',observed.reason) end
        local reserved,why=budget.reserve(intent)
        if not reserved then return decision('stop',why or 'Budget checkpoint failed') end
        -- The sent flag is durable before dispatch; a crash between these steps
        -- may conservatively fence an unsent action, never duplicate a paid one.
        if not budget.sent(intent.id) then budget.cancel(intent.id);return decision('stop','Sent checkpoint failed') end
        A.current=K.copy(intent)
        local ok,sent,reason=pcall(io.send,intent,run)
        if not ok or sent~=true then
            A.halted=true;A.reason='Dispatch unconfirmed: '..tostring(ok and reason or sent)
            return decision('stop',A.reason)
        end
        return decision('action','Sent; waiting for operation-specific receipt',intent)
    end
    function A.observe(view)
        local p=A.current;if not p then return nil end
        local ok,r=pcall(io.verify or function()end,p,view)
        if ok and type(r)=='table' and r.intentId==p.id and r.status=='confirmed' and r.proof==true
            and K.same(p.context,r.context,p.expected.scope) then
            r.debits=r.debits or {}
            if budget.settle(r) then A.current=nil;return r end
        end
        if K.finite(view.now) and view.now>=p.deadline and not p.timedOut then
            p.timedOut=true;A.halted=true;A.reason='Action deadline exceeded; no automatic resend'
            return {intentId=p.id,status='uncertain',context=K.copy(p.context),observedAt=view.now}
        end
        return nil
    end
    function A.stop(reason) A.halted=true;A.reason=tostring(reason or 'Stopped') end
    function A.pending() return A.current end
    return A
end

end)()

__modules.threats = (function()
-- Pure summaries of explicitly observed enemies; missing mechanics stay unknown.
return function(C)
    local T={}
    function T.summarize(view)
        local out={complete=view.enemiesComplete==true,alive=0,positions={},bossAlive=nil,air=nil,shields=nil}
        if type(view.enemies)~='table' or #view.enemies>120 then out.complete=false;return out end
        local knownAir,knownShield,bossKnown=true,true,true
        local air,shields,boss=0,0,false
        for _,u in ipairs(view.enemies) do
            if type(u)~='table' or not C.finite(u.health) or C.distance(u.pos,u.pos)~=0 then out.complete=false
            elseif u.health>0 then
                out.alive+=1;out.positions[#out.positions+1]=u.pos
                if type(u.air)=='boolean' then if u.air then air+=1 end else knownAir=false end
                if C.finite(u.shield) and u.shield>=0 then shields+=u.shield else knownShield=false end
                if type(u.boss)=='boolean' then boss=boss or u.boss else bossKnown=false end
            end
        end
        if out.complete then
            if knownAir then out.air=air end;if knownShield then out.shields=shields end
            if bossKnown then out.bossAlive=boss end
        end
        return out
    end
    function T.near(summary,pos,range)
        if type(summary)~='table' or not summary.complete or C.distance(pos,pos)~=0 or not C.finite(range) or range<=0 then return nil end
        for _,p in ipairs(summary.positions) do if C.distance(p,pos)<=range then return true end end
        return false
    end
    return T
end

end)()

__modules.abilities = (function()
-- Observed normal casts only. Unknown toggles/stacking/meters are not guessed.
return function(C)
    local A={}
    function A.choose(s,cfg,lastById)
        if cfg.autoAbilities~=true or s.enemiesComplete~=true or type(s.enemyUnits)~='table' then return nil end
        local gap=math.max(1,C.finite(cfg.abilityGap) and cfg.abilityGap or 3)
        for _,u in ipairs(s.units or {}) do
            local equipped=false
            for _,r in ipairs(s.roster or {}) do if r.uuid==u.uuid and r.id==u.id then equipped=true;break end end
            local aa=u.activeAttack
            local known=type(aa)=='string' and aa~='' and aa~='nil' and not aa:find(':',1,true)
            if equipped and known and u.role~='buff' and u.castReady==true and C.finite(u.lastCast) and C.finite(u.cooldown)
                and u.cooldown>0 and C.finite(u.range) and u.range>0 and C.distance(u.pos,u.pos)==0
                and (not lastById[u.id] or s.now-lastById[u.id]>=gap) then
                for _,enemy in ipairs(s.enemyUnits) do
                    if C.finite(enemy.health) and enemy.health>0 and C.distance(u.pos,enemy.pos)<=u.range then return u end
                end
            end
        end
        return nil
    end
    function A.proof(p,u)
        return u.key==p.key and u.uuid==p.uuid and u.id==p.id and u.activeAttack==p.activeAttack
            and C.finite(u.lastCast) and C.finite(p.lastCast) and u.lastCast>p.lastCast
    end
    return A
end

end)()

__modules.flow = (function()
-- Optional wave actions share the same runtime/transport as combat.
return function(C,cfg)
    local F={armed=false,pending=nil,confirmations=0,soldRoles={},seen={}}
    function F:arm(s) self.armed=true;self.run=s.run;self.round=s.roundToken;self.stage=s.stage;self.pending=nil;self.seen={};self.soldRoles={} end
    function F:stop(reason) self.armed=false;self.reason=reason;self.pending=nil end
    function F:chooseCard(offers,ranks,caps,counts)
        local best,rank
        for i,v in ipairs(offers or {}) do
            if i>12 then return nil,'Card offer exceeds bound' end
            local cap=caps[v.title]
            if type(v.title)=='string' and C.finite(ranks[v.title]) and C.finite(cap) and cap>=0
                and (cap==0 or (counts[v.title] or 0)<cap) then
                if not best or ranks[v.title]<rank then best=v;rank=ranks[v.title] end
            end
        end
        return best,best and 'Ranked current offer; applied-state receipt still required' or 'Every card is capped or unsupported'
    end
    function F:tick(s)
        if not self.armed then return nil end
        if self.stage~=s.stage or self.run~=s.run or self.round~=s.roundToken then self:stop('Wave policy context changed');return nil end
        if self.pending then
            local p=self.pending;local done=false
            if p.kind=='skip' then done=(s.wave>p.wave) or (s.wave==p.wave and s.skipFinished==true)
            elseif p.kind=='sell' and s.unitsComplete==true then
                done=true;for _,u in ipairs(s.units or {}) do if u.key==p.key then done=false;break end end
            end
            if done then
                self.confirmations+=1;self.pending=nil
                if p.kind=='sell' then self.soldRoles[p.role]=true end
            elseif s.now-p.at>8 then self:stop(p.kind..' feedback unconfirmed; no retry') end
            return nil
        end
        if s.resultVisible or not s.started then return nil end
        local sellWave=tonumber(cfg.sellAllWave) or 0;local farmWave=tonumber(cfg.sellFarmWave) or 0
        local all=sellWave>0 and s.wave>=sellWave;local farm=farmWave>0 and s.wave>=farmWave
        if (all or farm) and s.unitsComplete==true then
            for _,u in ipairs(s.units or {}) do
                if u.id~='bulma' and u.sellable==true and u.key and u.uuid and (all or u.role=='farm') then
                    self.pending={kind='sell',key=u.key,uuid=u.uuid,id=u.id,role=u.role or 'combat',at=s.now}
                    return {kind='sell',key=u.key,uuid=u.uuid,id=u.id}
                end
            end
            if all then self.soldRoles.all=true elseif farm then self.soldRoles.farm=true end
        end
        local offer=s.skipOffer
        if cfg.autoSkip==true and type(offer)=='table' and type(offer.token)=='string' and offer.wave==s.wave
            and s.skipFinished==false and not self.seen[offer.token]
            and ((tonumber(cfg.skipStopWave) or 0)==0 or s.wave<cfg.skipStopWave) then
            self.seen[offer.token]=true
            self.pending={kind='skip',token=offer.token,wave=s.wave,at=s.now}
            return {kind='skip',offerToken=offer.token,wave=s.wave}
        end
        return nil
    end
    return F
end

end)()

