__modules.reports = (function()
-- Bounded, redacted diagnostics and an independent explicit outbound queue.
return function(C,io)
    io=io or {};local R={events={},dropped=0,outcomes={},order={},wins=0,losses=0,unknown=0,
        queue={},notified={},notificationOrder={},notificationState='OFF'}
    local function redact(text)
        text=tostring(text):gsub('[\r\n]',' ')
        text=text:gsub('https?://[^%s]*[Ww][Ee][Bb][Hh][Oo][Oo][Kk][Ss]/[^%s]+','<webhook>')
        text=text:gsub('%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x','<unit>')
        return text:gsub(string.rep('%x',32),'<unit>')
    end
    function R:record(event)
        if type(event)~='table' then return end
        self.events[#self.events+1]={kind=redact(event.kind or 'event'):sub(1,40),detail=redact(event.detail or ''):sub(1,200)}
        if #self.events>500 then table.remove(self.events,1);self.dropped+=1 end
    end
    local function change(self,result,delta)
        local k=result=='Victory' and 'wins' or result=='Defeat' and 'losses' or 'unknown';self[k]=math.max(0,self[k]+delta)
    end
    function R:outcome(round,result)
        if type(round)~='string' or #round>200 then return false end
        if result~='Victory' and result~='Defeat' then result='unknown' end
        local before=self.outcomes[round]
        if before==result then return false end
        if before then
            if before~='unknown' and result~='unknown' then result='unknown';self.conflicted=self.conflicted or {};self.conflicted[round]=true end
            if self.conflicted and self.conflicted[round] then result='unknown' end
            change(self,before,-1)
        else self.order[#self.order+1]=round end
        self.outcomes[round]=result;change(self,result,1)
        if #self.order>100 then local old=table.remove(self.order,1);self.outcomes[old]=nil;if self.conflicted then self.conflicted[old]=nil end end
        self:record({kind='RESULT',detail=result..' | genuine observed outcome; rewards not inferred'})
        return true
    end
    function R:checkpoint()
        local out={wins=self.wins,losses=self.losses,unknown=self.unknown,order={},outcomes={},conflicted={}}
        for _,id in ipairs(self.order) do out.order[#out.order+1]=id;out.outcomes[id]=self.outcomes[id];out.conflicted[id]=self.conflicted and self.conflicted[id] or nil end
        return out
    end
    function R:restore(data)
        if type(data)~='table' or type(data.order)~='table' or #data.order>100 or type(data.outcomes)~='table' then return false end
        for _,k in ipairs({'wins','losses','unknown'}) do if not C.finite(data[k]) or data[k]<0 or data[k]%1~=0 or data[k]>1e9 then return false end end
        local order,outcomes,conflicted={},{},{}
        for _,id in ipairs(data.order) do
            local value=data.outcomes[id]
            if type(id)~='string' or #id>200 or outcomes[id] or not table.find({'Victory','Defeat','unknown'},value) then return false end
            order[#order+1]=id;outcomes[id]=value
            if type(data.conflicted)=='table' and data.conflicted[id]==true then conflicted[id]=true end
        end
        self.order=order;self.outcomes=outcomes;self.conflicted=conflicted
        self.wins=data.wins;self.losses=data.losses;self.unknown=data.unknown;return true
    end
    function R:render(limit)
        limit=math.clamp(C.finite(limit) and limit or 64000,500,64000)
        local head='RETAINED RUN SUMMARY | wins='..self.wins..' losses='..self.losses..' unknown='..self.unknown..
            '\nCurrency changes are observations, not attributed rewards. Retained events='..#self.events..' dropped='..self.dropped
        local out={head};local size=#head
        for i=#self.events,1,-1 do
            local e=self.events[i];local line=e.kind..' | '..e.detail
            if size+#line+1>limit then break end
            out[#out+1]=line;size+=#line+1
        end
        return table.concat(out,'\n')
    end
    function R:queueNotification(event,consent)
        if type(consent)~='table' or consent.enabled~=true or type(consent.url)~='string'
            or not consent.url:match('^https://discord%.com/api/webhooks/[%w_%-]+/[%w_%-]+$') then return false end
        if type(event)~='table' or type(event.id)~='string' or #event.id>200 or self.notified[event.id] or #self.queue>=20 then return false end
        self.notified[event.id]=true;self.notificationOrder[#self.notificationOrder+1]=event.id
        if #self.notificationOrder>100 then self.notified[table.remove(self.notificationOrder,1)]=nil end
        self.queue[#self.queue+1]={text=redact(event.text or ''):sub(1,1500),url=consent.url,attempts=0,due=0}
        self.notificationState='Queued with explicit send permission';return true
    end
    function R:tick(now)
        if self.worker then
            if now-self.worker.at>8 and not self.worker.expired then
                self.worker.expired=true;self.notificationState='Delivery unknown; no retry while worker outstanding'
            end
            return
        end
        local event=self.queue[1];if not event or now<event.due then return end
        if type(io.start)~='function' then self.notificationState='HTTP capability unavailable';return end
        event.attempts+=1
        local mark={at=now};self.worker=mark
        local function done(code)
            if self.worker~=mark then return end
            self.worker=nil
            if self.queue[1]~=event then self.notificationState='Previous request finished after permission changed';return end
            if mark.expired then table.remove(self.queue,1);self.notificationState='Late HTTP result; previous delivery unconfirmed';return end
            if code==429 and event.attempts<3 then event.due=now+30;self.notificationState='Rate limited; bounded retry pending'
            else table.remove(self.queue,1);self.notificationState=type(code)=='number' and code>=200 and code<300 and 'Delivered' or 'HTTP failed/unconfirmed; event dropped' end
        end
        local ok=pcall(io.start,event.url,event.text,done)
        if not ok then done(nil) end
    end
    function R:revokeNotifications()
        self.queue={};self.notified={};self.notificationOrder={};self.notificationState=self.worker and 'Permission revoked; already-sent HTTP cannot be undone' or 'OFF'
    end
    return R
end

end)()

__modules.inventory = (function()
-- Read-only parsing of an existing client-service export. No game/executor APIs.
return function(C)
    local I={}
    I.itemAliases={SacredTreasure={'sacred_treasure','SacredTreasure'},StarFruit={'StarFruit'},
        StarFruitBlue={'StarFruitBlue'},StarFruitRed={'StarFruitRed'},StarFruitGreen={'StarFruitGreen'},
        StarFruitEpic={'StarFruitEpic'},DungeonKey={'dungeon_key','DungeonKey'},
        RerollToken={'reroll_token','RerollToken'},StarRemnant={'star_remnant','StarRemnant'},
        StatCube={'stat_cube','StatCube'},PerfectStatCube={'perfect_stat_cube','PerfectStatCube'}}
    local function get(t,k) if type(t)=='table' then return rawget(t,k) end end
    local function tableAt(t,k) local v=get(t,k);return type(v)=='table' and v or nil end
    local function number(t,keys)
        for _,k in ipairs(keys) do local v=get(t,k);if C.finite(v) then return v end end
    end
    local function text(t,keys)
        for _,k in ipairs(keys) do
            local v=get(t,k)
            if type(v)=='string' and #v>0 and #v<=160 then return v end
        end
    end
    local traitNames={unique='Unique',divine='Divine',celestial='Celestial',reaper='Reaper',
        godspeed='Godspeed',sniper='Sniper',golden='Golden'}
    local function readUnit(key,t)
        if type(t)~='table' or type(key)~='string' or #key==0 or #key>160 then return nil end
        for _,alias in ipairs({'uuid','unique_id'}) do
            local explicit=get(t,alias)
            if explicit~=nil and (type(explicit)~='string' or explicit~=key) then return nil end
        end
        local id=text(t,{'unit_id','unitId','id'});if not id then return nil end
        local stats=tableAt(t,'stats') or t
        local u={uuid=key,id=id,statScope='collection',traits={},potential={}}
        local keys={damage={'damage','dmg'},spa={'spa','attack_cooldown'},range={'range','attack_range'},
            cost={'placement_cost','spawn_cost','place_cost'},level={'level'},
            takedowns={'takedowns','kills'},worthiness={'worthiness'}}
        for field,names in pairs(keys) do u[field]=number(stats,names) or number(t,names) end
        for field,names in pairs({damageGrade={'damage_grade','damageGrade'},spaGrade={'spa_grade','spaGrade'},
            rangeGrade={'range_grade','rangeGrade'}}) do u[field]=text(stats,names) or text(t,names) end
        local traits=tableAt(t,'traits')
        if traits then
            for i=1,4 do
                local v=rawget(traits,i)
                local raw=type(v)=='string' and v or text(v,{'trait','trait_id'})
                if raw and #raw<=48 then u.traits[#u.traits+1]=traitNames[raw:lower()] or raw end
            end
        end
        if #u.traits==0 then
            local raw=text(t,{'trait','trait_name'})
            if raw then u.traits[1]=traitNames[raw:lower()] or raw end
        end
        if #u.traits>0 then u.trait=table.concat(u.traits,' + ') end
        for _,field in ipairs({'stat_damage','stat_attack_cooldown','stat_range'}) do
            local v=get(t,field);if C.finite(v) then u.potential[field]=v end
        end
        return u
    end
    function I.read(service,userId)
        local out={valid=false,owned={},roster={},resources={},truncated=false,rejected=0,
            equippedComplete=false,equippedDeclared=0,reason='Client schema unavailable'}
        local session=tableAt(service,'session')
        local profile=tableAt(session,'profile_data')
        local collection=tableAt(tableAt(session,'collection'),'collection_profile_data')
        local owned=tableAt(collection,'owned_units')
        if not session or not owned then return out end
        for _,source in pairs({service,session,profile,collection}) do
            for _,key in ipairs({'user_id','player_id','UserId'}) do
                local id=get(source,key)
                if id~=nil and ((type(id)~='number' and type(id)~='string') or tonumber(id)~=userId) then
                    out.reason='Client owner mismatch/unverified';return out
                end
            end
        end
        out.valid=true;out.reason='Partial local client-service collection'
        local byUUID={}
        local function add(uuid)
            if type(uuid)~='string' then return nil end
            if byUUID[uuid] then return byUUID[uuid] end
            local u=readUnit(uuid,rawget(owned,uuid))
            if u then byUUID[uuid]=u;out.owned[#out.owned+1]=u else out.rejected+=1 end
            return u
        end
        local equipped=tableAt(collection,'equipped_units')
        if equipped then
            out.equippedComplete=true
            local key=nil
            for i=1,32 do
                key=next(equipped,key);if key==nil then break end
                local slot=type(key)=='number' and key or type(key)=='string' and tonumber(key)
                if not C.finite(slot) or slot%1~=0 or slot<1 or slot>8
                    or (type(key)=='string' and key~=tostring(slot)) then out.equippedComplete=false end
                if i==32 and next(equipped,key)~=nil then out.equippedComplete=false end
            end
            for slot=1,8 do
                local numeric=rawget(equipped,slot)
                local named=rawget(equipped,tostring(slot))
                local ambiguous=numeric~=nil and named~=nil and numeric~=named
                local uuid=numeric;if uuid==nil then uuid=named end
                if uuid~=nil then out.equippedDeclared+=1 end
                if ambiguous then out.rejected+=1;out.equippedComplete=false;uuid=nil end
                local u=add(uuid)
                if u then
                    -- A UUID occupying multiple slots is ambiguous, so never
                    -- manufacture a second equipped record for it.
                    if u.slot then out.rejected+=1;out.equippedComplete=false else u.slot=slot;out.roster[#out.roster+1]=u end
                elseif uuid~=nil then out.equippedComplete=false
                end
            end
        end
        local key=nil
        for _=1,400 do
            key=next(owned,key);if key==nil then break end
            add(key)
        end
        if key~=nil and next(owned,key)~=nil then out.truncated=true end
        table.sort(out.owned,function(a,b) return a.id==b.id and a.uuid<b.uuid or a.id<b.id end)
        local items=tableAt(tableAt(session,'inventory'),'inventory_profile_data')
        items=tableAt(items,'normal_items')
        if items then
            for label,aliases in pairs(I.itemAliases) do
                for _,id in ipairs(aliases) do
                    local amount=rawget(items,id)
                    if type(amount)=='table' then amount=number(amount,{'amount','count','quantity'}) end
                    if C.finite(amount) and amount>=0 then out.resources[label]=amount;break end
                end
            end
        end
        local rerolls=number(profile,{'trait_reroll_tokens'})
        if rerolls and rerolls>=0 then out.resources.RerollToken=rerolls end
        return out
    end
    function I.current(binding)
        if type(binding)~='table' then return nil end
        local entry=tableAt(binding.registry,binding.name)
        return tableAt(entry,'module') or entry
    end
    function I.named(roots,names)
        local out={}
        for i=1,math.min(#roots,97) do
            local root=rawget(roots,i)
            local value=type(root)=='table' and rawget(root,'value')
            if type(value)=='table' then
                local parents={value}
                for _,key in ipairs({'CLIENT_SERVICE','CORE_SERVICE','client_services','core_services','services','_services','modules','_modules'}) do
                    local nested=tableAt(value,key);if nested then parents[#parents+1]=nested end
                end
                for _,parent in ipairs(parents) do
                    for j=1,math.min(#names,8) do
                        local name=rawget(names,j)
                        if type(name)=='string' and not out[name] and tableAt(parent,name) then
                            out[name]={registry=parent,name=name,source=tostring(rawget(root,'source') or 'cache')..'.'..name}
                        end
                    end
                end
            end
        end
        return out
    end
    function I.find(roots,userId)
        local seen={}
        local containers={'CLIENT_SERVICE','client_services','services','_services','modules','_modules'}
        for _,serviceName in ipairs({'ItemInventoryServiceClient','StatsServiceClient','GUIService'}) do
            for i=1,math.min(#roots,97) do
                local root=roots[i]
                local value=root and root.value
                if type(value)=='table' then
                    local parents={{value=value,path=root.source}}
                    for _,name in ipairs(containers) do
                        local v=tableAt(value,name)
                        if v then parents[#parents+1]={value=v,path=root.source..'.'..name} end
                    end
                    for _,parent in ipairs(parents) do
                        local entry=tableAt(parent.value,serviceName)
                        local service=tableAt(entry,'module') or entry
                        if service and not seen[service] then
                            seen[service]=true
                            local snapshot=I.read(service,userId)
                            if snapshot.valid then return {service=service,source=parent.path..'.'..serviceName,
                                registry=parent.value,name=serviceName,snapshot=snapshot} end
                        end
                    end
                end
            end
        end
        return nil
    end
    return I
end

end)()

__modules.trial = (function()
-- Explicit single-action Story tests. No route claim, replay or emitted tick actions.
return function(C,cfg,log)
    local T={state='IDLE',reason='No supervised action attempted',pending=nil,placements=0,upgrades=0,
        attemptRun=nil,attempted={}}
    function T:quote(kind,s,p)
        if s.externalControllerActive then return nil,'Close Zeno before using a native action test' end
        if kind~='place' and kind~='upgrade' then return nil,'Unsupported test action' end
        if self.pending or s.transportBlocked then return nil,'A request/test is still pending' end
        if s.mutationFence then return nil,'Prior mutation lacks exact feedback; enter a fresh match' end
        if self.state=='UNCONFIRMED' and self.attemptRun==s.run then
            return nil,'Previous test unconfirmed; inspect the report and enter a fresh match'
        end
        if self.attemptRun==s.run and self.attempted[kind] then
            return nil,'One '..kind..' test already attempted this run; inspect the report'
        end
        if not s.inMatch or not s.stageVerified or not s.modeVerified or s.mode~='Story' then
            return nil,'An observed free Story match is required'
        end
        if not s.started or s.resultVisible then return nil,'Start waves in an unfinished match first' end
        if s.unitsComplete~=true then return nil,'Tower observation incomplete' end
        if not C.finite(s.now) or not C.finite(s.rosterAt) or s.now-s.rosterAt<0 or s.now-s.rosterAt>15 then
            return nil,'Fresh equipped records unavailable'
        end
        if type(p)~='table' or type(p.entries)~='table' or #p.entries~=1 or p.source~='user-recorded' then
            return nil,'Record exactly one own tower first'
        end
        if not C.contextMatches(p,s) then return nil,'Recorded stage/mode/place differs' end
        if p.costScale~=nil and (not C.finite(s.costScale) or p.costScale~=s.costScale) then
            return nil,'Cost modifier changed or became unknown; record again'
        end
        local e=p.entries[1]
        if type(e)~='table' or type(e.uuid)~='string' or e.uuid=='' or type(e.id)~='string' or e.id==''
            or C.distance(e.pos,e.pos)~=0 or not C.finite(e.cost) or e.cost<=0 then
            return nil,'Recorded position or deployment price invalid'
        end
        local equipped
        for _,u in ipairs(s.roster or {}) do if u.uuid==e.uuid and u.id==e.id then equipped=u;break end end
        if not equipped then return nil,'Recorded unit is no longer equipped' end
        if p.testSlot~=nil and (p.testSlot~=cfg.trialSlot or equipped.slot~=p.testSlot) then
            return nil,'Selected test slot changed; record its current tower again'
        end
        if C.finite(equipped.cost) and equipped.cost~=e.cost then return nil,'Deployment price changed; record again' end
        local q={kind=kind,uuid=e.uuid,id=e.id,pos={e.pos[1],e.pos[2],e.pos[3]},cost=e.cost,
            slot=equipped.slot,run=s.run,stage=s.stage,mode=s.mode,placeId=s.placeId,at=s.now}
        if kind=='place' then
            for _,u in ipairs(s.units or {}) do
                if u.uuid==e.uuid and u.id==e.id then
                    return nil,'Target already placed; save its test profile, then use a fresh copy of this stage'
                end
                if C.distance(u.pos,e.pos)<=3 then return nil,'Another tower occupies the recorded position' end
            end
        else
            local found
            for _,u in ipairs(s.units or {}) do
                if u.uuid==e.uuid and u.id==e.id and C.distance(u.pos,e.pos)<=3 then
                    if found then return nil,'Recorded upgrade target is ambiguous' end
                    found=u
                end
            end
            if not found or not found.key then return nil,'Recorded tower is not present' end
            if not C.finite(found.level) or found.level<0 or found.level%1~=0
                or not C.finite(found.nextCost) or found.nextCost<=0 then
                return nil,'Current upgrade level or next price unknown'
            end
            q.key=found.key;q.level=found.level;q.cost=found.nextCost
        end
        local reserve=C.finite(cfg.reserve) and math.max(0,cfg.reserve) or 0
        if not C.finite(s.cash) or s.cash-reserve<q.cost then
            return nil,'Need '..q.cost..' match Yen + '..reserve..' reserve; have '..tostring(s.cash or '?')
        end
        return q
    end
    function T:begin(kind,s,p,displayed)
        local q,why=self:quote(kind,s,p)
        if not q then return nil,why end
        if type(displayed)~='table' or not C.finite(displayed.at) or s.now-displayed.at<0 or s.now-displayed.at>5
            or displayed.kind~=q.kind or displayed.uuid~=q.uuid or displayed.id~=q.id or displayed.cost~=q.cost
            or displayed.run~=q.run or not C.contextMatches(displayed,s) or displayed.key~=q.key
            or displayed.slot~=q.slot or displayed.level~=q.level or C.distance(displayed.pos,q.pos)>0.01 then
            return nil,'Displayed price/target changed or expired; review the refreshed button'
        end
        if self.attemptRun~=s.run then self.attemptRun=s.run;self.attempted={} end
        self.attempted[kind]=true
        q.before={};for _,u in ipairs(s.units or {}) do if u.key then q.before[u.key]=true end end
        q.cashBefore=s.cash
        self.pending=q;self.state='WAITING';self.reason='One '..kind..' request; awaiting exact tower readback'
        self.last={kind=kind,id=q.id,cost=q.cost,cashBefore=s.cash}
        log:add('TRIAL ATTEMPT',kind..' '..q.id..' | quoted match Yen='..q.cost..'; no automatic retry')
        return {kind=kind,uuid=q.uuid,id=q.id,pos=table.clone(q.pos),key=q.key}
    end
    local function finish(self,state,reason,s)
        self.pending=nil;self.state=state;self.reason=reason
        if self.last and s then self.last.cashAfter=s.cash end
        log:add('TRIAL '..state,reason)
    end
    function T:cancel(reason)
        if self.pending then finish(self,'UNCONFIRMED',reason or 'Test cancelled; result unconfirmed') end
    end
    function T:tick(s)
        local q=self.pending;if not q then return nil end
        if not C.finite(s.now) or s.now-q.at>8 or s.now<q.at then
            finish(self,'UNCONFIRMED','Feedback deadline exceeded; no automatic retry',s);return nil
        end
        if s.run~=q.run or not s.inMatch or not s.stageVerified or not s.modeVerified or s.mode~='Story'
            or not C.contextMatches(q,s)
            or s.unitsComplete~=true or s.resultVisible then
            finish(self,'UNCONFIRMED','Match/observation changed before confirmation',s);return nil
        end
        if q.kind=='place' then
            local match,ambiguous=C.placementVerified(q,s.units)
            if ambiguous then finish(self,'UNCONFIRMED','Multiple matching new towers; placement is ambiguous',s)
            elseif match then
                self.placements+=1
                finish(self,'OBSERVED','New exact '..q.id..' tower observed at the recorded position after request',s)
            end
        else
            for _,u in ipairs(s.units or {}) do
                if u.key==q.key and u.uuid==q.uuid and u.id==q.id and C.distance(u.pos,q.pos)<=3
                    and C.finite(u.level) and u.level>q.level then
                    if u.level==q.level+1 then
                        self.upgrades+=1
                        finish(self,'OBSERVED','Exact '..q.id..' tower upgrade '..q.level..' → '..u.level..' observed',s)
                    else finish(self,'UNCONFIRMED','Unexpected upgrade jump; result unconfirmed',s) end
                    break
                end
            end
        end
        return nil -- this observer never starts a second action
    end
    function T:text()
        local out='Single-action test: '..self.state..' | '..self.reason..
            '\nObserved trial placements='..self.placements..' | upgrades='..self.upgrades
        if self.last then
            out=out..'\nLast test='..self.last.kind..' '..self.last.id..' | quoted match Yen='..self.last.cost..
                ' | cash before='..tostring(self.last.cashBefore)..' after='..tostring(self.last.cashAfter or '?')..
                ' (balance changes are not attributed costs)'
        end
        return out
    end
    return T
end

end)()

__modules.team = (function()
-- Pure recorded-team orchestration. No Rukia-route claims or native calls.
return function(C,cfg,log)
    local T={armed=false,state='IDLE',reason='Team Auto OFF',pending=nil,
        placements=0,upgrades=0,wins=0,losses=0,runs=0,reportDue=false}
    local function role(e)
        return table.find({'combat','farm','buff'},e.role) and e.role or 'unknown'
    end
    local function matches(s,p)
        local out,used={},{}
        for i,e in ipairs(p.entries) do
            local found
            for _,u in ipairs(s.units or {}) do
                if u.key and u.uuid==e.uuid and u.id==e.id and C.distance(u.pos,e.pos)<=3 then
                    if found and found.key~=u.key then return nil,'Multiple towers match recorded target '..i end
                    found=u
                end
            end
            if found then
                if used[found.key] then return nil,'One tower matches multiple recorded targets' end
                used[found.key]=true;out[i]=found
            end
        end
        return out
    end
    function T:coverage(s,p)
        local count,total,missing=0,0,{}
        for _,u in ipairs(s.roster or {}) do
            total+=1;local found=false
            for i,e in ipairs(type(p)=='table' and type(p.entries)=='table' and p.entries or {}) do
                if i>24 then break end
                if type(e)=='table' and e.uuid==u.uuid and e.id==u.id then found=true;break end
            end
            if found then count+=1 else missing[#missing+1]='slot '..tostring(u.slot)..' '..u.id end
        end
        return count,total,missing
    end
    function T:readiness(s,p)
        local b=C.profileReadiness(s,p,cfg)
        if not s.modeVerified or s.mode~='Story' then b[#b+1]='Team Auto currently supports observed Story only' end
        if type(p)~='table' or p.kind~='team-v1' then b[#b+1]='Record a team profile first' end
        local covered,total,missing=self:coverage(s,p)
        if s.rosterComplete~=true then b[#b+1]='Declared equipped-slot data is incomplete or ambiguous' end
        if total==0 or covered~=total then b[#b+1]='Record every equipped slot: '..table.concat(missing,', ') end
        for _,u in ipairs(s.roster or {}) do
            if not C.finite(u.cost) or u.cost<=0 then b[#b+1]='Current deployment price unknown: '..u.id end
        end
        for _,u in ipairs(s.units or {}) do
            if type(p)=='table' and type(p.entries)=='table' then
                for _,e in ipairs(p.entries) do
                    if type(e)=='table' and u.uuid==e.uuid and u.id==e.id and C.distance(u.pos,u.pos)~=0 then
                        b[#b+1]='Live recorded tower position unavailable';break
                    end
                end
            end
        end
        if not C.finite(cfg.reserve) or cfg.reserve<0 or not C.finite(cfg.maxSeconds) or cfg.maxSeconds<30
            or not C.finite(cfg.maxRuns) or cfg.maxRuns<1 then b[#b+1]='Invalid session budget/limits' end
